.comparison-grid-foot { border-bottom: 0; }
.comparison-gates { display: grid; gap: 8px; align-content: start; }
.comparison-gate-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
