     unreadable columns. */
  .comparison-grid { grid-template-columns: minmax(0, 1fr) !important; }
  .comparison-cell + .comparison-cell { border-left: 0; }
  .comparison-gutter { padding-bottom: 0; border-bottom: 0; font-weight: 600; }
  .comparison-value { text-align: left; }
  .comparison-gate-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
"""
CSS.write_text(css, encoding="utf-8")

dead = [
