 * that into a result.
 */
export function marginIsConclusive(ci: [number, number] | null): boolean {
  if (!ci) return false;
  return ci[0] > 0 || ci[1] < 0;
}

/** Gates whose failure leaves no trace in the utility at all.
 *
 * G2 excludes collisions from `U_S` by contract, and no objective
 * reflects G6's missing observation channel. A reader comparing a
 * blocked candidate's mark against an eligible one has to be told that
 * the two most disqualifying failures are the two the number cannot see.
 */
export const GATES_INVISIBLE_TO_UTILITY = ["G2", "G6"] as const;

export function invisibleFailures(standing: Standing): string[] {
  return standing.blockingGates.filter((gate) =>
    (GATES_INVISIBLE_TO_UTILITY as readonly string[]).includes(gate),
  );
}

