import type { DecisionCard, DecisionRun, RunCandidate } from "@/lib/decisions";
import {
  invisibleFailures,
  marginIsConclusive,
  outOf100,
  standings,
  verdictOf,
} from "@/lib/conclusion";

function candidate(overrides: Partial<RunCandidate> = {}): RunCandidate {
  return {
    candidate_id: "cand_a",
