    // Consistent with the two being equal. Printing the mean alone
    // turns that into a result.
    expect(marginIsConclusive([-0.002, 0.006])).toBe(false);
    expect(marginIsConclusive(null)).toBe(false);
  });
});

describe("the failures the number cannot see", () => {
  it("names G2 and G6", () => {
    // Collisions are excluded from U_S by contract and no objective
    // reflects a missing observation channel — the two most
    // disqualifying failures are the two the mark does not move for.
    const { blocked } = standings([
      candidate({
        cleared_gates: false,
        recommendation_eligible: false,
        blocking_gates: ["G2", "G4", "G6"],
      }),
    ]);
    expect(invisibleFailures(blocked[0])).toEqual(["G2", "G6"]);
  });

  it("says nothing for failures the objectives do reflect", () => {
    // G3 lands in U_R and G4 in U_C, so the mark already carries them.
    const { blocked } = standings([
      candidate({
        cleared_gates: false,
        recommendation_eligible: false,
        blocking_gates: ["G3", "G4"],
      }),
    ]);
    expect(invisibleFailures(blocked[0])).toEqual([]);
  });
});

